  rule_set text,
  name_source text,
  skip_reason text,
  status text,
  collection_id text,
  slack_channel text,
  slack_ts text,
  error text,
  "createdAt" timestamptz not null default now(),
  "updatedAt" timestamptz not null default now(),
  unique (key)
);

