-- ===== Phase 5 · Google Shopping feed (google-shopping-feed-optimization/supabase/schema.sql)
-- Tables for the Google Shopping feed optimisation template (Supabase / Postgres).
-- Run once in the Supabase SQL editor, or let the Setup lane run it.

create table if not exists feed_fields (
  id integer generated by default as identity primary key,
  channel text,
  sort_order double precision,
  field text,
  kind text,
  target text,
  source text,
  required boolean,
