create table if not exists feed_status (
  id integer generated by default as identity primary key,
  product_id text,
  state text,
  missing text,
  app_fields text,
  sent text,
  google_state text,
  google_issues text,
  slack_channel text,
  slack_ts text,
  checked_at timestamptz,
  read_at timestamptz,
  "createdAt" timestamptz not null default now(),
  "updatedAt" timestamptz not null default now(),
  unique (product_id)
);

-- ===== Phase 5 · Pinterest pins (pinterest-automation/supabase/schema.sql)
create table if not exists pins (
  id integer generated by default as identity primary key,
  product_id text,
  product_title text,
  handle text,
  pin_no integer,
  pin_kind text,
  board_key text,
  board_name text,
  board_id text,
  title text,
  description text,
  alt_text text,
  headline text,
  product_line text,
  review_quote text,
  review_rating integer,
  review_author text,
  review_source text,
  image_url text,
  source_image text,
  photo_kind text,
  shopify_file_id text,
  link text,
  problems text,
  status text,
  slack_channel text,
  slack_ts text,
  decided_by text,
  decided_at timestamptz,
  post_id text,
  scheduled_for timestamptz,
  posted_at timestamptz,
  pin_url text,
  error text,
  "createdAt" timestamptz not null default now(),
  "updatedAt" timestamptz not null default now()
);
create table if not exists pin_reviews (
  id integer generated by default as identity primary key,
  product_handle text,
  rating integer,
  quote text,
  author text,
  source text,
  verified boolean,
  "createdAt" timestamptz not null default now(),
  "updatedAt" timestamptz not null default now()
);
create unique index if not exists pins_product_image on pins (product_id, pin_kind, source_image);
create index if not exists pins_status on pins (status);
create index if not exists pin_reviews_handle on pin_reviews (product_handle);

-- ===== Phase 5 · Instagram posts (instagram-automation/supabase/schema.sql)
create table if not exists instagram_posts (
  id integer generated by default as identity primary key,
  product_id text,
  product_title text,
  handle text,
  headline text,
  product_line text,
  caption text,
  alt_text text,
  source_image text,
  photo_kind text,
  image_url text,
  shopify_file_id text,
  link text,
  problems text,
  status text,
  slack_channel text,
  slack_ts text,
  decided_by text,
  decided_at timestamptz,
  scheduled_for timestamptz,
  container_id text,
  media_id text,
  post_url text,
  posted_at timestamptz,
  error text,
  "createdAt" timestamptz not null default now(),
  "updatedAt" timestamptz not null default now()
);
create table if not exists instagram_token (
  id integer generated by default as identity primary key,
  account text,
  token text,
  ig_user_id text,
  username text,
  expires_at timestamptz,
  refreshed_at timestamptz,
  "createdAt" timestamptz not null default now(),
  "updatedAt" timestamptz not null default now()
);
create unique index if not exists instagram_posts_product on instagram_posts (product_id);
create index if not exists instagram_posts_status on instagram_posts (status);
create unique index if not exists instagram_token_account on instagram_token (account);

-- ===== The glue: conductor, review page links, buyer guides
-- The conductor: which stage each live product is at, and the last product it enrolled.
create table if not exists store_pipeline (
  id integer generated by default as identity primary key,
  product_id text not null,
  title text,
  stage integer not null default 0,
  stage_name text,
  tags_added text,
  stage_started_at timestamptz not null default now(),
  done boolean not null default false,
  note text,
  "createdAt" timestamptz not null default now(),
  "updatedAt" timestamptz not null default now(),
  unique (product_id)
);
create index if not exists store_pipeline_open on store_pipeline (done, stage_started_at);

create table if not exists store_state (
  key text primary key,
  value text,
  "updatedAt" timestamptz not null default now()
);

-- Who ran what from /store, and every decision made on the review page.
create table if not exists store_activity (
  id integer generated by default as identity primary key,
  source text,
  user_id text,
  user_name text,
  action text,
  detail text,
  "createdAt" timestamptz not null default now()
);

-- Buyer guides: one row per collection, the draft waiting in Slack and what went live.
create table if not exists buyer_guides (
  id integer generated by default as identity primary key,
  collection_id text not null,
  handle text,
  title text,
  keyword text,
  volume double precision,
  status text,
  revision integer not null default 0,
  draft_html text,
  draft_text text,
  words integer,
  flags text,
  questions text,
  model text,
  error text,
  slack_channel text,
  slack_ts text,
  decided_by text,
  live_at timestamptz,
  "createdAt" timestamptz not null default now(),
  "updatedAt" timestamptz not null default now(),
  unique (collection_id)
);

-- What /store status counts: one row per review queue. Generated by build.py from system.json.
create or replace view store_queues as
  select 'supplier-offers'::text as queue, 'Supplier offers'::text as label, 1::int as phase, '#review-supplier-offers'::text as channel, count(*)::int as waiting, min(x.since)::timestamptz as oldest
  from (select id::text as id, case when title ilike brand || ' %' then title else concat_ws(' ', brand, coalesce(title, source_sku)) end as label, concat_ws(' · ', mpn, source, case when cost is not null then 'cost ' || round(cost::numeric, 2) end) as detail, id || ':' || card_nonce as value, card_ts as ts, null::text as channel, "updatedAt" as since from offers where status = 'pending_review' and card_nonce is not null) x
  union all
  select 'product-drafts'::text as queue, 'Product drafts'::text as label, 1::int as phase, '#review-product-drafts'::text as channel, count(*)::int as waiting, min(x.since)::timestamptz as oldest
  from (select id::text as id, case when title ilike brand || ' %' then title else concat_ws(' ', brand, coalesce(title, source_sku)) end as label, concat_ws(' · ', mpn, product_id) as detail, id || ':' || card_nonce as value, draft_card_ts as ts, null::text as channel, "updatedAt" as since from offers where status = 'drafted' and card_nonce is not null) x
  union all
  select 'titles'::text as queue, 'Product titles'::text as label, 1::int as phase, '#review-titles'::text as channel, count(*)::int as waiting, min(x.since)::timestamptz as oldest
  from (select id::text as id, new_title as label, 'was: ' || old_title as detail, product_id as value, slack_ts as ts, null::text as channel, "updatedAt" as since from title_drafts where status = 'pending') x
  union all
  select 'discontinued'::text as queue, 'Discontinued products'::text as label, 2::int as phase, '#review-discontinued'::text as channel, count(*)::int as waiting, min(x.since)::timestamptz as oldest
  from (select id::text as id, title as label, concat_ws(' · ', handle, 'redirect to ' || redirect_to) as detail, product_id as value, slack_ts as ts, slack_channel as channel, "updatedAt" as since from retire_queue where status = 'proposed') x
  union all
  select 'pricing'::text as queue, 'Held prices'::text as label, 2::int as phase, '#review-pricing'::text as channel, count(*)::int as waiting, min(x.since)::timestamptz as oldest
  from (select id::text as id, coalesce(title, sku) as label, concat_ws(' · ', sku, 'now ' || current_price, 'proposed ' || proposed_price) as detail, variant_id || '|' || proposed_price as value, slack_ts as ts, slack_channel as channel, "updatedAt" as since from price_decisions where status = 'held') x
  union all
  select 'documents'::text as queue, 'Manuals and spec sheets'::text as label, 3::int as phase, '#review-documents'::text as channel, count(*)::int as waiting, min(x.since)::timestamptz as oldest
  from (select id::text as id, coalesce(product_title, model) || ': ' || coalesce(doc_title, doc_type) as label, concat_ws(' · ', doc_type, url) as detail, id::text as value, slack_ts as ts, slack_channel as channel, "updatedAt" as since from documents where status = 'in_review') x
  union all
  select 'images'::text as queue, 'Product images'::text as label, 3::int as phase, '#review-images'::text as channel, count(*)::int as waiting, min(x.since)::timestamptz as oldest
  from (select id::text as id, title as label, concat_ws(' · ', vendor, mpn) as detail, product_id as value, card_ts as ts, card_channel as channel, "updatedAt" as since from image_queue where status = 'review') x
  union all
  select 'attributes'::text as queue, 'Product attributes'::text as label, 3::int as phase, '#review-attributes'::text as channel, count(*)::int as waiting, min(x.since)::timestamptz as oldest
  from (select slack_ts as id, case when count(distinct product_id) = 1 then max(product_title) else count(distinct product_id) || ' products: ' || left(string_agg(distinct product_title, ', '), 160) end as label, count(*) || ' values: ' || left(string_agg(key || ' = ' || value, ', '), 240) as detail, case when count(distinct product_id) = 1 then max(product_id) else 'bulk' end as value, slack_ts as ts, max(slack_channel) as channel, min("updatedAt") as since, case when count(distinct product_id) = 1 then 'attr_approve' else 'bulk_approve' end as approve_action, case when count(distinct product_id) = 1 then 'attr_reject' else 'bulk_reject' end as reject_action from attribute_values where review_status = 'pending' and slack_ts is not null group by slack_ts) x
  union all
  select 'descriptions'::text as queue, 'Product descriptions'::text as label, 3::int as phase, '#review-descriptions'::text as channel, count(*)::int as waiting, min(x.since)::timestamptz as oldest
  from (select id::text as id, title as label, left(draft_text, 240) as detail, product_id as value, slack_ts as ts, slack_channel as channel, "updatedAt" as since from description_drafts where status = 'pending') x
  union all
  select 'faqs'::text as queue, 'Product FAQs'::text as label, 3::int as phase, '#review-faqs'::text as channel, count(*)::int as waiting, min(x.since)::timestamptz as oldest
  from (select id::text as id, title as label, concat_ws(' · ', model, 'revision ' || revision) as detail, json_build_object('p', product_id, 'r', revision)::text as value, slack_ts as ts, slack_channel as channel, "updatedAt" as since from faq_drafts where status = 'review') x
  union all
  select 'manufacturer-reviews'::text as queue, 'Manufacturer reviews'::text as label, 3::int as phase, '#review-manufacturer-reviews'::text as channel, count(*)::int as waiting, min(x.since)::timestamptz as oldest
  from (select id::text as id, product_title as label, concat_ws(' · ', review_count || ' reviews', 'average ' || average, url) as detail, id::text as value, card_ts as ts, card_channel as channel, "updatedAt" as since from review_sources where status = 'ready' and card_ts is not null) x
  union all
  select 'accessories'::text as queue, 'Compatible accessories'::text as label, 3::int as phase, '#review-accessories'::text as channel, count(*)::int as waiting, min(x.since)::timestamptz as oldest
  from (select id::text as id, title as label, concat_ws(' · ', model, 'revision ' || revision) as detail, json_build_object('a', regexp_replace(accessory_id, '\D', '', 'g')::bigint, 'r', revision)::text as value, slack_ts as ts, slack_channel as channel, "updatedAt" as since from accessory_reviews where status = 'review') x
  union all
  select 'videos'::text as queue, 'Product videos'::text as label, 3::int as phase, '#review-videos'::text as channel, count(*)::int as waiting, min(x.since)::timestamptz as oldest
  from (select id::text as id, product_title || ': ' || title as label, concat_ws(' · ', channel_name, coverage, 'https://youtu.be/' || video_id) as detail, id::text as value, card_ts as ts, card_channel as channel, "updatedAt" as since from video_candidates where status = 'pending') x
  union all
  select 'collection-proposals'::text as queue, 'Collection proposals'::text as label, 4::int as phase, '#review-collection-proposals'::text as channel, count(*)::int as waiting, min(x.since)::timestamptz as oldest
  from (select id::text as id, kind || ': ' || title as label, concat_ws(' · ', handle, source) as detail, id::text as value, slack_ts as ts, slack_channel as channel, "updatedAt" as since from collection_proposals where status = 'pending') x
  union all
  select 'collection-copy'::text as queue, 'Collection copy'::text as label, 4::int as phase, '#review-collection-copy'::text as channel, count(*)::int as waiting, min(x.since)::timestamptz as oldest
  from (select id::text as id, title as label, concat_ws(' · ', keyword, case when volume is not null then volume::int || ' searches' end, left(intro, 200)) as detail, handle as value, null::text as ts, null::text as channel, "updatedAt" as since from collection_copy where status = 'review') x
  union all
  select 'google'::text as queue, 'Held from Google'::text as label, 5::int as phase, '#review-google'::text as channel, count(*)::int as waiting, min(x.since)::timestamptz as oldest
  from (select product_id as id, 'Product ' || product_id as label, state as detail, product_id as value, slack_ts as ts, slack_channel as channel, "updatedAt" as since from feed_status where state = 'held') x
  union all
  select 'pins'::text as queue, 'Pinterest pins'::text as label, 5::int as phase, '#review-pins'::text as channel, count(*)::int as waiting, min(x.since)::timestamptz as oldest
  from (select id::text as id, coalesce(title, product_title) as label, concat_ws(' · ', product_title, pin_kind) as detail, id::text as value, slack_ts as ts, slack_channel as channel, "updatedAt" as since from pins where status = 'draft' and slack_ts is not null) x
  union all
  select 'instagram'::text as queue, 'Instagram posts'::text as label, 5::int as phase, '#review-instagram'::text as channel, count(*)::int as waiting, min(x.since)::timestamptz as oldest
  from (select id::text as id, coalesce(headline, product_title) as label, product_title as detail, id::text as value, slack_ts as ts, slack_channel as channel, "updatedAt" as since from instagram_posts where status = 'draft' and slack_ts is not null) x
  union all
  select 'buyer-guides'::text as queue, 'Buyer guides'::text as label, 4::int as phase, '#review-buyer-guides'::text as channel, count(*)::int as waiting, min(x.since)::timestamptz as oldest
  from (select id::text as id, title as label, concat_ws(' · ', keyword, words || ' words', flags) as detail, json_build_object('c', collection_id, 'r', revision)::text as value, slack_ts as ts, slack_channel as channel, "updatedAt" as since from buyer_guides where status = 'review') x;
